import { NextResponse } from 'next/server'
import { db } from '@/lib/db'

// POST /api/conversations/[id]/messages — append a user message
// (the assistant response is generated by /api/chat)
export async function POST(req: Request, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params
  const body = await req.json()

  const msg = await db.message.create({
    data: {
      conversationId: id,
      role: body.role || 'user',
      content: body.content || '',
      actions: JSON.stringify(body.actions || []),
      attachments: JSON.stringify(body.attachments || []),
      confidence: body.confidence || 0,
      autonomyLevel: body.autonomyLevel ?? 2,
      status: body.status || 'done',
    },
  })

  // If user message, update conversation title from first message
  if (body.role === 'user' || body.role === undefined) {
    const count = await db.message.count({ where: { conversationId: id } })
    if (count <= 1) {
      const title = body.content.slice(0, 60) + (body.content.length > 60 ? '…' : '')
      await db.conversation.update({ where: { id }, data: { title } })
    }
    // Touch updatedAt
    await db.conversation.update({ where: { id }, data: { updatedAt: new Date() } })
  }

  return NextResponse.json(
    { ...msg, actions: JSON.parse(msg.actions || '[]'), attachments: JSON.parse(msg.attachments || '[]') },
    { status: 201 }
  )
}
